// The Mix Print Design category tree, shared by the Services and Products pages.
// Loaded into the database by migration 20261102090000_shared_category_tree (generated by
// scripts/generate-taxonomy-sql.ts). After that, everything is edited in Admin → Categories.

export type TaxonomyNode = {
  slug: string; // unique among siblings; forms the URL, e.g. /services/board-maker/3d-sign-board
  name: string;
  short: string; // one-line summary for cards and meta descriptions (≤ 160 characters)
  content: string; // page description shown on the category page (editable in admin)
  priceUnit?: string; // e.g. "per sq. ft"; the price itself is left empty for the owner to set
  children?: TaxonomyNode[];
};
